<?phpnamespace app\store\controller;use app\store\model\User as UserModel;use app\store\model\RechargeLog as RechargeLogModel;use think\facade\View;/** * 用户控制器 */class User extends Controller{	/**     * 用户列表     */    public function index(string $search = '',string $gender = 'all')    {        $model = new UserModel;        $list = $model->getList($search,$gender);        return View::fetch('index', compact('list','gender','search'));    }	/**     * 余额充值    */    public function recharge()    {        if ($this->request->isPost()) {            $model = new RechargeLogModel;            $data = $this->postData('data');            $data['mode'] = 20;//管理操作            if ($model->add($data)) {                return $this->renderSuccess('操作成功');            }            $error = $model->getError() ?: '操作失败';            return $this->renderError($error);        }    }        /**     * 积分充值    */    public function score()    {        if ($this->request->isPost()) {            $model = new RechargeLogModel;            $data = $this->postData('data');            $data['mode'] = 20;//管理操作            $data['type'] = 20;//积分充值            if ($model->add($data)) {                return $this->renderSuccess('操作成功');            }            $error = $model->getError() ?: '操作失败';            return $this->renderError($error);        }    }        /**     * 粉丝转用户     */    public function syncFans()    {        $model = new UserModel;        if($model->syncFans()){            return $this->renderSuccess('同步成功');        }        $error = $model->getError() ?: '同步失败';        return $this->renderError($error);    }}